insert into public.bien_savoir (bien_id, agence, categorie, titre, contenu_fr, public, statut, motif_relecture, source, sources, source_date, ordre)
select bi.id, coalesce(bi.agence, 'dcb'), 'poubelles_tri', 'Poubelles et tri',
  concat_ws(E'\n',
    'Jours de collecte : ' || coalesce(b.jours, 'à confirmer (dépend de la rue ou du type de bac)' || case when c.lien is not null then ' ; vérifier sur ' || c.lien else '' end),
    'Lieu des bacs : ' || coalesce(b.lieu, 'à compléter'),
    'Tri (' || b.commune || ') : ' || c.tri,
    case when c.verre is not null then 'Verre : ' || c.verre end,
    case when c.dech is not null then 'Déchèterie / encombrants : ' || c.dech end,
    'Source : ' || coalesce(b.src_jours, c.src1) || ' (consultée le 23/10/2026)'),
  array['voyageur', 'ia', 'ae'], 'a_relire',
  'Relevé sur les sites officiels le 23/10/2026 — à relire avant de le montrer aux voyageurs.' || case when b.certitude = 'a_confirmer' then ' Jours de collecte À CONFIRMER.' else '' end || case when b.note is not null then ' ' || b.note else '' end,
  'powerhouse',
  case when b.src_jours is not null then jsonb_build_array(jsonb_build_object('type', 'web', 'url', b.src_jours, 'titre', 'Jours de collecte (source officielle)', 'consulte_le', '2026-10-23')) else '[]'::jsonb end || c.srcs,
  date '2026-10-23', 0
from b join c on c.commune = b.commune
join public.bien bi on bi.code = b.code
where not exists (select 1 from public.bien_savoir s where s.bien_id = bi.id and s.categorie = 'poubelles_tri' and s.statut <> 'archive');
